-- P3.2 activity reporting: versioned measures with explicit legacy provenance.
create function app_private.activity_measure(uid uuid,cid uuid,gid uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare result jsonb;begin
 if not app_private.is_manager() or not exists(select 1 from public.content_items where id=cid and workspace_id=app_private.current_workspace()) then raise exception 'access_denied';end if;
 with visits as (
 select a.first_opened_at first_open,a.last_opened_at last_open,a.open_count,a.active_seconds from public.lesson_release_activity a join public.content_releases r on r.id=a.release_id where a.user_id=uid and r.content_id=cid and (gid is null or r.group_id=gid)
 union all select opened_at,last_opened_at,open_count,active_seconds from public.lesson_activity where user_id=uid and content_id=cid and gid is null
 ),practice as (
 select p.attempts,p.completed from public.practice_release_progress p join public.content_releases r on r.id=p.release_id where p.user_id=uid and r.content_id=cid and (gid is null or r.group_id=gid)
 union all select attempts,completed from public.practice_progress where user_id=uid and content_id=cid and gid is null
 ) select jsonb_build_object('firstOpen',(select min(first_open) from visits),'lastOpen',(select max(last_open) from visits),'openCount',coalesce((select sum(open_count) from visits),0),'activeSeconds',coalesce((select sum(active_seconds) from visits),0),'practiceAttempted',(select count(*) from practice),'practiceCompleted',(select count(*) from practice where completed),'practiceAttempts',coalesce((select sum(attempts) from practice),0),
 'assignmentAttempts',(select count(*) from public.attempts a join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id left join public.enrollments e on e.id=a.enrollment_id where a.user_id=uid and ass.content_id=cid and (gid is null or e.group_id=gid)),
 'pendingReviews',(select count(*) from public.reviews re join public.attempts a on a.id=re.attempt_id join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id left join public.enrollments e on e.id=a.enrollment_id where a.user_id=uid and ass.content_id=cid and re.status<>'reviewed' and (gid is null or e.group_id=gid)),
 'feedback',(select re.feedback from public.reviews re join public.attempts a on a.id=re.attempt_id join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id left join public.enrollments e on e.id=a.enrollment_id where a.user_id=uid and ass.content_id=cid and re.status='reviewed' and (gid is null or e.group_id=gid) order by re.updated_at desc limit 1),
 'legacyUnattributed',exists(select 1 from public.lesson_activity where user_id=uid and content_id=cid) or exists(select 1 from public.practice_progress where user_id=uid and content_id=cid),
 'versions',coalesce((select jsonb_agg(jsonb_build_object('releaseId',r.id,'version',r.content_version,'group',g.name,'year',y.label,'openCount',a.open_count,'activeSeconds',a.active_seconds,'practiceAttempts',(select coalesce(sum(attempts),0) from public.practice_release_progress where user_id=uid and release_id=r.id))) from public.content_releases r join public.groups g on g.id=r.group_id join public.academic_years y on y.id=r.academic_year_id left join public.lesson_release_activity a on a.release_id=r.id and a.user_id=uid where r.content_id=cid and (gid is null or r.group_id=gid) and (a.user_id is not null or exists(select 1 from public.practice_release_progress where user_id=uid and release_id=r.id))),'[]')) into result;return result;end $$;
create function app_private.management_activity_page(view_name text,target_id uuid,subject_filter uuid default null,page_number int default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare rows jsonb;begin
 if not app_private.is_manager() or page_number<0 or page_number>1000 then raise exception 'access_denied';end if;
 if view_name='content' then
 if not exists(select 1 from public.content_items where id=target_id and workspace_id=app_private.current_workspace()) then raise exception 'access_denied';end if;
 select coalesce(jsonb_agg(app_private.activity_measure(v.id,target_id)||jsonb_build_object('userId',v.id,'username',v.username,'firstName',v.first_name,'lastName',v.last_name,'currentlyAccessible',app_private.user_can_read_content(v.id,target_id))),'[]') into rows from (
 select p.* from public.profiles p join public.workspace_memberships m on m.user_id=p.id where m.workspace_id=app_private.current_workspace() and (app_private.user_can_read_content(p.id,target_id) or exists(select 1 from public.lesson_activity where user_id=p.id and content_id=target_id) or exists(select 1 from public.lesson_release_activity a join public.content_releases r on r.id=a.release_id where a.user_id=p.id and r.content_id=target_id) or exists(select 1 from public.practice_release_progress a join public.content_releases r on r.id=a.release_id where a.user_id=p.id and r.content_id=target_id) or exists(select 1 from public.attempts a join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id where a.user_id=p.id and ass.content_id=target_id)) order by p.username limit 50 offset page_number*50) v;
 elsif view_name='account' then
 if not exists(select 1 from public.workspace_memberships where user_id=target_id and workspace_id=app_private.current_workspace()) then raise exception 'access_denied';end if;
 select coalesce(jsonb_agg(app_private.activity_measure(target_id,v.id)||jsonb_build_object('contentId',v.id,'subjectId',v.subject_id,'title',v.title,'currentlyAccessible',app_private.user_can_read_content(target_id,v.id))),'[]') into rows from (
 select c.* from public.content_items c where c.workspace_id=app_private.current_workspace() and (subject_filter is null or c.subject_id=subject_filter) and (app_private.user_can_read_content(target_id,c.id) or exists(select 1 from public.lesson_activity where user_id=target_id and content_id=c.id) or exists(select 1 from public.lesson_release_activity a join public.content_releases r on r.id=a.release_id where a.user_id=target_id and r.content_id=c.id) or exists(select 1 from public.practice_release_progress a join public.content_releases r on r.id=a.release_id where a.user_id=target_id and r.content_id=c.id) or exists(select 1 from public.attempts a join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id where a.user_id=target_id and ass.content_id=c.id)) order by c.level_code,c.module,c.sort_order,c.id limit 50 offset page_number*50) v;
 else raise exception 'invalid_activity_view';end if;return rows;end $$;
create function public.management_activity_page(view_name text,target_id uuid,subject_filter uuid default null,page_number int default 0) returns jsonb language sql stable security invoker set search_path='' as $$ select app_private.management_activity_page(view_name,target_id,subject_filter,page_number) $$;
create or replace function app_private.management_content_activity(cid uuid) returns jsonb language sql stable security definer set search_path='' as $$ select app_private.management_activity_page('content',cid,null,0) $$;
create or replace function app_private.management_account_activity(uid uuid) returns jsonb language sql stable security definer set search_path='' as $$ select app_private.management_activity_page('account',uid,null,0) $$;

create or replace function app_private.management_group_activity(gid uuid,sid uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare yid uuid;begin
 if not app_private.is_manager() or not exists(select 1 from public.groups where id=gid and workspace_id=app_private.current_workspace()) then raise exception 'access_denied';end if;select academic_year_id into yid from public.groups where id=gid;
 return (with members as(select distinct user_id from public.enrollments where group_id=gid),releases as(select r.*,c.subject_id from public.content_releases r join public.content_items c on c.id=r.content_id where r.group_id=gid and (sid is null or c.subject_id=sid)),eligible as(select distinct m.user_id,r.content_id from members m cross join releases r where exists(select 1 from public.enrollments e where e.group_id=gid and e.user_id=m.user_id and (e.ended_at is null or e.ended_at>=r.created_at::date))),
 relevant_attempts as(select a.*,q.kind,q.prompt from public.attempts a join public.questions q on q.id=a.question_id join public.assignments ass on ass.id=q.assignment_id where ass.academic_year_id=yid and (sid is null or ass.subject_id=sid) and exists(select 1 from public.assignment_targets t where t.assignment_id=ass.id and t.group_id=gid and t.allowed) and exists(select 1 from public.enrollments e where e.group_id=gid and e.user_id=a.user_id and (a.enrollment_id=e.id or (a.enrollment_id is null and a.submitted_at::date>=e.started_at and (e.ended_at is null or a.submitted_at::date<=e.ended_at)))))
 select jsonb_build_object('eligible',(select count(*) from eligible),'opened',(select count(distinct (a.user_id,r.content_id)) from public.lesson_release_activity a join releases r on r.id=a.release_id),'practiceAttempted',(select count(*) from public.practice_release_progress p join releases r on r.id=p.release_id),'practiceCompleted',(select count(*) from public.practice_release_progress p join releases r on r.id=p.release_id where p.completed),'practiceAttempts',(select coalesce(sum(p.attempts),0) from public.practice_release_progress p join releases r on r.id=p.release_id),
 'pendingReviews',(select count(*) from public.reviews re join relevant_attempts a on a.id=re.attempt_id where re.status<>'reviewed'),'averageAssignmentAttempts',coalesce((select avg(n) from(select user_id,count(*) n from relevant_attempts group by user_id)v),0),'topErrors',coalesce((select jsonb_agg(to_jsonb(v)) from(select prompt question,count(*) errors from relevant_attempts where correct=false group by prompt order by errors desc limit 10)v),'[]'),'legacyNote','Attività P3.1 senza versione/gruppo non attribuite agli aggregati di gruppo; consultabili per account/contenuto.'));end $$;

revoke execute on all functions in schema app_private from public,anon;
revoke execute on all functions in schema public from public,anon;
grant execute on function app_private.management_activity_page(text,uuid,uuid,int),public.management_activity_page(text,uuid,uuid,int) to authenticated;
-- activity_measure is an internal helper, not exposed or directly executable by API roles.
revoke execute on function app_private.activity_measure(uuid,uuid,uuid) from authenticated;
